{
  "name": "impromptu-r2",
  "version": "0.0.0",
  "private": true,
  "packageManager": "bun@1.3.14",
  "workspaces": [
    "apps/*",
    "services/*",
    "packages/*"
  ],
  "scripts": {
    "check:repo": "bun run scripts/verify-repo.ts",
    "lint": "biome check .",
    "typecheck": "tsc --noEmit",
    "test": "bun test",
    "check": "bun run check:repo && bun run lint && bun run typecheck && bun run test"
  },
  "devDependencies": {
    "@biomejs/biome": "2.2.0",
    "@types/bun": "1.2.20",
    "typescript": "5.9.2"
  }
}

{
  "$schema": "https://biomejs.dev/schemas/2.2.0/schema.json",
  "files": {
    "includes": [
      "**",
      "!.git",
      "!node_modules",
      "!docs/*.html",
      "!docs/*.pdf",
      "!.omo/senpi-task",
      "!.senpi"
    ]
  },
  "formatter": {
    "enabled": true,
    "indentStyle": "space",
    "indentWidth": 2,
    "lineWidth": 100
  },
  "linter": {
    "enabled": true,
    "rules": {
      "recommended": true
    }
  },
  "javascript": {
    "formatter": {
      "quoteStyle": "double",
      "semicolons": "always"
    }
  }
}

import { existsSync, readFileSync } from "node:fs";

const requiredFiles = [
  "README.md",
  "CONTRIBUTING.md",
  "docs/AI-BOUNDARY.md",
  "docs/DEMO-SCOPE.md",
  "docs/PWA-구현-최적화-연구보고서.md",
  "docs/PWA-구현-최적화-연구보고서.html",
  "docs/신청서.pdf",
  ".omo/hyperplan/pwa-presentation-debate.md",
  ".omo/plans/impromptu-r2-hyperplan.md",
  ".omo/ulw-research/20260814-040838/sources-ledger.md",
] as const;

const missingFiles = requiredFiles.filter((path) => !existsSync(path));

if (missingFiles.length > 0) {
  throw new Error(`Missing required repository files: ${missingFiles.join(", ")}`);
}

const packageManifest = JSON.parse(readFileSync("package.json", "utf8")) as {
  name?: unknown;
  private?: unknown;
};

if (packageManifest.name !== "impromptu-r2" || packageManifest.private !== true) {
  throw new Error("package.json must identify the private impromptu-r2 workspace");
}

const gitignore = readFileSync(".gitignore", "utf8");
const requiredIgnoreEntries = [
  ".env",
  ".omo/senpi-task/",
  ".senpi/",
  "models/",
  "uploads/",
] as const;
const missingIgnoreEntries = requiredIgnoreEntries.filter((entry) => !gitignore.includes(entry));

if (missingIgnoreEntries.length > 0) {
  throw new Error(`Missing required .gitignore entries: ${missingIgnoreEntries.join(", ")}`);
}

console.log(`Repository policy verified (${requiredFiles.length} required files).`);

import { describe, expect, test } from "bun:test";
import { existsSync, readFileSync } from "node:fs";

describe("repository policy", () => {
  test("uses the impromptu-r2 private workspace identity", () => {
    const manifest = JSON.parse(readFileSync("package.json", "utf8")) as {
      name?: unknown;
      private?: unknown;
    };

    expect(manifest).toMatchObject({
      name: "impromptu-r2",
      private: true,
    });
  });

  test("ships the application, approved plan, research, and server-only AI boundary", () => {
    expect(existsSync("docs/신청서.pdf")).toBe(true);
    expect(existsSync("docs/PWA-구현-최적화-연구보고서.md")).toBe(true);
    expect(existsSync("docs/PWA-구현-최적화-연구보고서.html")).toBe(true);
    expect(existsSync(".omo/plans/impromptu-r2-hyperplan.md")).toBe(true);
    expect(existsSync(".omo/ulw-research/20260814-040838/sources-ledger.md")).toBe(true);

    const boundary = readFileSync("docs/AI-BOUNDARY.md", "utf8");
    expect(boundary).toContain("All model execution");
    expect(boundary).toContain("Browser bundles may not contain or invoke");
  });

  test("ignores secrets, runtime state, uploads, and model artifacts", () => {
    const gitignore = readFileSync(".gitignore", "utf8");

    for (const entry of [".env", ".senpi/", ".omo/senpi-task/", "uploads/", "models/"]) {
      expect(gitignore).toContain(entry);
    }
  });
});

