{
  "name": "@impromptu/ui",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "exports": {
    ".": "./src/index.ts",
    "./styles.css": "./src/styles.css"
  },
  "scripts": {
    "build": "vite build",
    "typecheck": "tsc --noEmit"
  },
  "peerDependencies": {
    "react": "^19.1.1",
    "react-dom": "^19.1.1"
  },
  "devDependencies": {
    "@types/react": "19.1.10",
    "@types/react-dom": "19.1.7",
    "@vitejs/plugin-react": "5.0.2",
    "react": "19.1.1",
    "react-dom": "19.1.1",
    "vite": "7.1.3"
  }
}

{
  "extends": "../../tsconfig.json",
  "compilerOptions": {
    "allowImportingTsExtensions": false,
    "jsx": "react-jsx",
    "lib": ["ES2023", "DOM", "DOM.Iterable"],
    "types": ["vite/client"]
  },
  "include": ["src/**/*.ts", "src/**/*.tsx", "vite.config.ts"]
}

import { defineConfig } from "vite";
import react from "@vitejs/plugin-react";

export default defineConfig({
  plugins: [react()],
  build: {
    lib: {
      entry: "src/index.ts",
      formats: ["es"],
      fileName: "index",
    },
    rollupOptions: {
      external: ["react", "react-dom", "react/jsx-runtime"],
    },
  },
});

:root {
  color-scheme: dark;

  --color-ink: oklch(96% 0.018 92deg);
  --color-paper: oklch(16% 0.02 235deg);
  --color-accent: oklch(78% 0.17 71deg);
  --color-accent-strong: oklch(84% 0.17 76deg);
  --color-success: oklch(76% 0.16 153deg);
  --color-warning: oklch(82% 0.16 82deg);
  --color-danger: oklch(69% 0.2 27deg);
  --color-info: oklch(75% 0.12 225deg);
  --color-transparent: transparent;
  --color-shadow: oklch(5% 0.02 235deg / 45%);
  --color-noise: oklch(100% 0 0deg / 4%);

  --surface-canvas: var(--color-paper);
  --surface-panel: oklch(21% 0.026 235deg / 88%);
  --surface-panel-strong: oklch(25% 0.03 235deg);
  --surface-inset: oklch(12% 0.018 235deg / 72%);
  --surface-accent: var(--color-accent);
  --text-primary: var(--color-ink);
  --text-secondary: oklch(78% 0.025 90deg);
  --text-on-accent: oklch(16% 0.03 67deg);
  --border-subtle: oklch(100% 0 0deg / 13%);
  --border-emphasis: oklch(100% 0 0deg / 28%);
  --focus-ring: var(--color-accent-strong);
  --atmosphere-a: oklch(55% 0.13 228deg / 25%);
  --atmosphere-b: oklch(65% 0.16 60deg / 12%);

  --font-display: "Book Antiqua", "Iowan Old Style", "Noto Serif KR", serif;
  --font-body: Aptos, "Noto Sans KR", "Apple SD Gothic Neo", sans-serif;
  --font-mono: "Cascadia Mono", "D2Coding", monospace;
  --text-caption: 0.75rem;
  --text-small: 0.875rem;
  --text-body: 1rem;
  --text-lead: clamp(1.08rem, 2vw, 1.25rem);
  --text-title: clamp(1.5rem, 4vw, 2.5rem);
  --text-display: clamp(2.5rem, 8vw, 6.5rem);
  --line-tight: 1.04;
  --line-title: 1.15;
  --line-body: 1.6;
  --tracking-tight: -0.035em;
  --tracking-wide: 0.12em;
  --weight-regular: 400;
  --weight-medium: 600;
  --weight-bold: 750;

  --space-0: 0;
  --space-1: 0.25rem;
  --space-2: 0.5rem;
  --space-3: 0.75rem;
  --space-4: 1rem;
  --space-5: 1.25rem;
  --space-6: 1.5rem;
  --space-8: 2rem;
  --space-10: 2.5rem;
  --space-12: 3rem;
  --space-16: 4rem;
  --space-20: 5rem;

  --size-hairline: 0.0625rem;
  --size-control: 2.75rem;
  --size-target: 3rem;
  --size-icon-sm: 0.5rem;
  --size-icon: 0.75rem;
  --size-brand-mark: 2.5rem;
  --size-rail: 15rem;
  --size-copy: 66ch;
  --size-card-min: 17rem;
  --size-stage-copy: 48rem;
  --size-page: 90rem;
  --size-full: 100%;
  --size-viewport: 100dvh;

  --radius-sm: 0.375rem;
  --radius-md: 0.75rem;
  --radius-lg: 1.5rem;
  --radius-pill: 999rem;
  --shadow-panel: 0 1.5rem 4rem var(--color-shadow);
  --shadow-focus: 0 0 0 0.2rem var(--focus-ring);
  --shadow-accent: 0 1rem 3rem oklch(70% 0.15 65deg / 18%);

  --duration-fast: 140ms;
  --duration-reveal: 520ms;
  --duration-ambient: 14s;
  --ease-out: cubic-bezier(0.2, 0.8, 0.2, 1);
  --delay-1: 70ms;
  --delay-2: 140ms;
  --delay-3: 210ms;
  --opacity-muted: 0.72;
  --opacity-soft: 0.48;
  --blur-atmosphere: 5rem;
  --rotate-accent: -2deg;
  --translate-reveal: 1rem;
  --layer-skip: 100;
}

[data-surface="console"] {
  --surface-canvas: oklch(14% 0.027 244deg);
  --surface-panel: oklch(20% 0.035 240deg / 90%);
  --surface-panel-strong: oklch(24% 0.043 235deg);
  --surface-inset: oklch(10% 0.022 244deg / 75%);
  --color-accent: oklch(79% 0.17 73deg);
  --atmosphere-a: oklch(51% 0.14 224deg / 30%);
  --atmosphere-b: oklch(72% 0.14 66deg / 12%);
}

[data-surface="stage"] {
  color-scheme: light;
  --surface-canvas: oklch(94% 0.035 85deg);
  --surface-panel: oklch(98% 0.018 87deg / 90%);
  --surface-panel-strong: oklch(100% 0.01 90deg);
  --surface-inset: oklch(90% 0.045 82deg / 80%);
  --text-primary: oklch(20% 0.035 248deg);
  --text-secondary: oklch(43% 0.035 248deg);
  --border-subtle: oklch(25% 0.03 245deg / 14%);
  --border-emphasis: oklch(25% 0.03 245deg / 30%);
  --color-accent: oklch(58% 0.19 27deg);
  --color-accent-strong: oklch(50% 0.2 26deg);
  --text-on-accent: oklch(98% 0.01 90deg);
  --focus-ring: oklch(53% 0.18 232deg);
  --color-shadow: oklch(35% 0.05 70deg / 18%);
  --atmosphere-a: oklch(75% 0.15 72deg / 28%);
  --atmosphere-b: oklch(68% 0.14 223deg / 18%);
}

@import "./tokens.css";

* {
  box-sizing: border-box;
}

html {
  min-width: var(--size-card-min);
  min-height: var(--size-full);
  background: var(--surface-canvas);
}

body {
  min-width: var(--size-card-min);
  min-height: var(--size-viewport);
  margin: var(--space-0);
  color: var(--text-primary);
  background:
    radial-gradient(circle at 12% 8%, var(--atmosphere-a), var(--color-transparent) 34%),
    radial-gradient(circle at 86% 74%, var(--atmosphere-b), var(--color-transparent) 38%),
    var(--surface-canvas);
  font-family: var(--font-body);
  font-size: var(--text-body);
  line-height: var(--line-body);
  text-rendering: optimizeLegibility;
}

button,
a,
input {
  font: inherit;
}

button,
a {
  -webkit-tap-highlight-color: var(--color-transparent);
}

a {
  color: inherit;
}

:focus-visible {
  outline: none;
  box-shadow: var(--shadow-focus);
}

::selection {
  color: var(--text-on-accent);
  background: var(--color-accent);
}

.ui-skip-link {
  position: fixed;
  z-index: var(--layer-skip);
  inset-block-start: var(--space-3);
  inset-inline-start: var(--space-3);
  padding: var(--space-3) var(--space-4);
  border-radius: var(--radius-md);
  color: var(--text-on-accent);
  background: var(--color-accent);
  font-weight: var(--weight-bold);
  transform: translateY(calc(-1 * var(--size-full) - var(--space-8)));
  transition: transform var(--duration-fast) var(--ease-out);
}

.ui-skip-link:focus {
  transform: translateY(var(--space-0));
}

.ui-brand {
  display: inline-flex;
  gap: var(--space-3);
  align-items: center;
  text-decoration: none;
}

.ui-brand__mark {
  display: grid;
  width: var(--size-brand-mark);
  height: var(--size-brand-mark);
  place-items: center;
  border: var(--size-hairline) solid var(--border-emphasis);
  border-radius: var(--radius-md);
  color: var(--text-on-accent);
  background: var(--color-accent);
  box-shadow: var(--shadow-accent);
  font-family: var(--font-display);
  font-size: var(--text-lead);
  font-weight: var(--weight-bold);
  transform: rotate(var(--rotate-accent));
}

.ui-brand__copy {
  display: grid;
  gap: var(--space-0);
  line-height: var(--line-title);
}

.ui-brand__name {
  font-family: var(--font-display);
  font-weight: var(--weight-bold);
  letter-spacing: var(--tracking-tight);
}

.ui-brand__eyebrow,
.ui-eyebrow {
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: var(--text-caption);
  font-weight: var(--weight-medium);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
}

.ui-button {
  display: inline-flex;
  min-height: var(--size-control);
  gap: var(--space-2);
  align-items: center;
  justify-content: center;
  padding: var(--space-3) var(--space-5);
  border: var(--size-hairline) solid var(--color-transparent);
  border-radius: var(--radius-pill);
  cursor: pointer;
  font-weight: var(--weight-bold);
  text-decoration: none;
  transition:
    transform var(--duration-fast) var(--ease-out),
    background var(--duration-fast) var(--ease-out),
    border-color var(--duration-fast) var(--ease-out);
}

.ui-button:hover {
  transform: translateY(calc(-1 * var(--size-hairline)));
}

.ui-button:active {
  transform: translateY(var(--space-0));
}

.ui-button--primary {
  color: var(--text-on-accent);
  background: var(--color-accent);
  box-shadow: var(--shadow-accent);
}

.ui-button--quiet {
  color: var(--text-primary);
  border-color: var(--border-emphasis);
  background: var(--surface-panel);
}

.ui-button--danger {
  color: var(--color-ink);
  background: var(--color-danger);
}

.ui-button:disabled {
  cursor: not-allowed;
  opacity: var(--opacity-soft);
  transform: none;
}

.ui-badge {
  display: inline-flex;
  width: fit-content;
  gap: var(--space-2);
  align-items: center;
  padding: var(--space-1) var(--space-3);
  border: var(--size-hairline) solid var(--border-subtle);
  border-radius: var(--radius-pill);
  color: var(--text-secondary);
  background: var(--surface-inset);
  font-family: var(--font-mono);
  font-size: var(--text-caption);
  font-weight: var(--weight-medium);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
}

.ui-badge--accent {
  color: var(--color-accent-strong);
  border-color: var(--color-accent);
}

.ui-badge--success {
  color: var(--color-success);
}

.ui-badge--warning {
  color: var(--color-warning);
}

.ui-status-dot {
  width: var(--size-icon-sm);
  height: var(--size-icon-sm);
  flex: none;
  border-radius: var(--radius-pill);
  background: currentColor;
  box-shadow: 0 0 var(--space-3) currentColor;
}

.ui-panel {
  position: relative;
  overflow: hidden;
  padding: clamp(var(--space-5), 4vw, var(--space-8));
  border: var(--size-hairline) solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--surface-panel);
  box-shadow: var(--shadow-panel);
  backdrop-filter: blur(var(--space-3));
}

.ui-panel--inset {
  border-radius: var(--radius-md);
  background: var(--surface-inset);
  box-shadow: none;
}

.ui-panel__header {
  display: flex;
  gap: var(--space-4);
  align-items: flex-start;
  justify-content: space-between;
  margin-block-end: var(--space-5);
}

.ui-panel__title {
  margin: var(--space-0);
  font-family: var(--font-display);
  font-size: var(--text-title);
  line-height: var(--line-title);
  letter-spacing: var(--tracking-tight);
}

.ui-shell {
  width: min(var(--size-full), var(--size-page));
  min-height: var(--size-viewport);
  margin-inline: auto;
  padding: clamp(var(--space-4), 3vw, var(--space-8));
}

.ui-shell__header {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-4);
  align-items: center;
  justify-content: space-between;
  padding-block-end: var(--space-8);
}

.ui-shell__body {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(var(--size-full), var(--size-rail)), 1fr));
  gap: var(--space-6);
  align-items: start;
}

.ui-shell__body--focused {
  display: block;
  max-width: var(--size-stage-copy);
  margin-inline: auto;
}

.ui-reveal {
  animation: ui-reveal var(--duration-reveal) var(--ease-out) both;
}

.ui-reveal--2 {
  animation-delay: var(--delay-2);
}

.ui-reveal--3 {
  animation-delay: var(--delay-3);
}

@keyframes ui-reveal {
  from {
    opacity: var(--space-0);
    transform: translateY(var(--translate-reveal));
  }
}

@media (prefers-reduced-motion: reduce) {
  *,
  *::before,
  *::after {
    scroll-behavior: auto !important;
    animation-duration: var(--duration-fast) !important;
    animation-iteration-count: 1 !important;
    transition-duration: var(--duration-fast) !important;
  }
}

@media (forced-colors: active) {
  .ui-button,
  .ui-panel,
  .ui-brand__mark,
  .ui-badge {
    border: var(--size-hairline) solid CanvasText;
  }
}

import type { ButtonHTMLAttributes, ReactNode } from "react";

type ButtonVariant = "primary" | "quiet" | "danger";

export interface ButtonProps extends ButtonHTMLAttributes<HTMLButtonElement> {
  children: ReactNode;
  variant?: ButtonVariant;
}

export function Button({ children, className = "", variant = "primary", ...props }: ButtonProps) {
  return (
    <button className={`ui-button ui-button--${variant} ${className}`.trim()} {...props}>
      {children}
    </button>
  );
}

import type { HTMLAttributes, ReactNode } from "react";

export type BadgeTone = "neutral" | "accent" | "success" | "warning";

export interface BadgeProps extends HTMLAttributes<HTMLSpanElement> {
  children: ReactNode;
  tone?: BadgeTone;
}

export function Badge({ children, className = "", tone = "neutral", ...props }: BadgeProps) {
  const toneClass = tone === "neutral" ? "" : ` ui-badge--${tone}`;
  return (
    <span className={`ui-badge${toneClass} ${className}`.trim()} {...props}>
      {children}
    </span>
  );
}

import type { HTMLAttributes } from "react";

export interface BrandProps extends HTMLAttributes<HTMLDivElement> {
  eyebrow: string;
  name?: string;
}

export function Brand({ className = "", eyebrow, name = "Impromptu", ...props }: BrandProps) {
  return (
    <div className={`ui-brand ${className}`.trim()} {...props}>
      <span className="ui-brand__mark" aria-hidden="true">
        I
      </span>
      <span className="ui-brand__copy">
        <span className="ui-brand__name">{name}</span>
        <span className="ui-brand__eyebrow">{eyebrow}</span>
      </span>
    </div>
  );
}

import type { HTMLAttributes, ReactNode } from "react";

export interface PanelProps extends HTMLAttributes<HTMLElement> {
  action?: ReactNode;
  children: ReactNode;
  title?: string;
  tone?: "default" | "inset";
}

export function Panel({
  action,
  children,
  className = "",
  title,
  tone = "default",
  ...props
}: PanelProps) {
  const toneClass = tone === "inset" ? " ui-panel--inset" : "";
  return (
    <section className={`ui-panel${toneClass} ${className}`.trim()} {...props}>
      {title ? (
        <header className="ui-panel__header">
          <h2 className="ui-panel__title">{title}</h2>
          {action}
        </header>
      ) : null}
      {children}
    </section>
  );
}

import type { HTMLAttributes, ReactNode } from "react";

export interface ShellProps extends HTMLAttributes<HTMLDivElement> {
  children: ReactNode;
  focused?: boolean;
  header: ReactNode;
}

export function Shell({ children, className = "", focused = false, header, ...props }: ShellProps) {
  return (
    <div className={`ui-shell ${className}`.trim()} {...props}>
      <header className="ui-shell__header">{header}</header>
      <main id="main-content" className={`ui-shell__body${focused ? " ui-shell__body--focused" : ""}`}>
        {children}
      </main>
    </div>
  );
}

export function SkipLink() {
  return (
    <a className="ui-skip-link" href="#main-content">
      Skip to content
    </a>
  );
}

import type { HTMLAttributes } from "react";

export interface StatusDotProps extends HTMLAttributes<HTMLSpanElement> {
  label: string;
}

export function StatusDot({ label, ...props }: StatusDotProps) {
  return <span className="ui-status-dot" aria-label={label} role="img" {...props} />;
}

