{
  "name": "@impromptu/console",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --port 4173",
    "build": "vite build",
    "preview": "vite preview --port 4173",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@impromptu/ui": "workspace:*",
    "react": "19.1.1",
    "react-dom": "19.1.1",
    "react-router-dom": "7.8.2"
  },
  "devDependencies": {
    "@types/react": "19.1.10",
    "@types/react-dom": "19.1.7",
    "@vitejs/plugin-react": "5.0.2",
    "vite": "7.1.3"
  }
}

{
  "extends": "../../tsconfig.json",
  "compilerOptions": {
    "allowImportingTsExtensions": false,
    "jsx": "react-jsx",
    "lib": ["ES2023", "DOM", "DOM.Iterable"],
    "types": ["vite/client", "bun"]
  },
  "include": ["src/**/*.ts", "src/**/*.tsx", "vite.config.ts"]
}

import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [react()],
  build: {
    sourcemap: true,
  },
});

const CACHE_NAME = "impromptu-console-shell-v1";
const APP_SHELL = ["/", "/index.html", "/manifest.webmanifest", "/icon.svg"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(APP_SHELL)));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) => Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key)))),
  );
});

self.addEventListener("fetch", (event) => {
  const requestUrl = new URL(event.request.url);
  if (event.request.method !== "GET" || requestUrl.origin !== self.location.origin) {
    return;
  }

  event.respondWith(
    fetch(event.request).catch(() =>
      caches.match(event.request).then((cached) => cached ?? caches.match("/index.html")),
    ),
  );
});

export function registerConsoleServiceWorker() {
  if ("serviceWorker" in navigator && import.meta.env.PROD) {
    void navigator.serviceWorker.register("/sw.js", { scope: "/" });
  }
}

import "@impromptu/ui/styles.css";
import "./console.css";

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";

import { AuthProvider, ConsoleRoutes } from "./App";
import { registerConsoleServiceWorker } from "./registerServiceWorker";

const root = document.getElementById("root");

if (!root) {
  throw new Error("Console root element is missing");
}

document.documentElement.dataset.surface = "console";

createRoot(root).render(
  <StrictMode>
    <BrowserRouter>
      <AuthProvider>
        <ConsoleRoutes />
      </AuthProvider>
    </BrowserRouter>
  </StrictMode>,
);

registerConsoleServiceWorker();

import {
  Badge,
  Brand,
  Button,
  Panel,
  Shell,
  StatusDot,
} from "@impromptu/ui";
import {
  createContext,
  type ReactNode,
  useContext,
  useMemo,
  useState,
} from "react";
import { Link, Navigate, NavLink, Outlet, Route, Routes, useLocation } from "react-router-dom";

interface AuthState {
  authenticated: boolean;
  signIn: () => void;
  signOut: () => void;
}

const AuthContext = createContext<AuthState | null>(null);

export interface AuthProviderProps {
  children: ReactNode;
  initialAuthenticated?: boolean;
}

export function AuthProvider({ children, initialAuthenticated = false }: AuthProviderProps) {
  const [authenticated, setAuthenticated] = useState(initialAuthenticated);
  const value = useMemo(
    () => ({
      authenticated,
      signIn: () => setAuthenticated(true),
      signOut: () => setAuthenticated(false),
    }),
    [authenticated],
  );

  return <AuthContext value={value}>{children}</AuthContext>;
}

function useAuth() {
  const auth = useContext(AuthContext);
  if (!auth) {
    throw new Error("AuthProvider is required");
  }
  return auth;
}

function RequireAuth() {
  const { authenticated } = useAuth();
  const location = useLocation();

  return authenticated ? <Outlet /> : <Navigate to="/sign-in" replace state={{ from: location.pathname }} />;
}

function PublicOnly() {
  return useAuth().authenticated ? <Navigate to="/" replace /> : <Outlet />;
}

function ConsoleHeader() {
  return (
    <>
      <Brand eyebrow="Presenter Console" />
      <Badge tone="success">
        <StatusDot label="Local preview ready" />
        Local preview
      </Badge>
    </>
  );
}

function SignInPage() {
  const { signIn } = useAuth();

  return (
    <Shell focused header={<ConsoleHeader />}>
      <Panel className="console-sign-in ui-reveal">
        <p className="ui-eyebrow">Private origin</p>
        <h1>Private presentation control</h1>
        <p className="console-lead">
          Your setup, coaching, and team notes stay here. Nothing on this screen belongs on the
          audience display.
        </p>
        <Button onClick={signIn}>Enter private workspace</Button>
        <p className="console-caption">Foundation preview - no account or backend connection yet.</p>
      </Panel>
    </Shell>
  );
}

function PrivateNavigation() {
  const { signOut } = useAuth();

  return (
    <aside className="console-rail ui-reveal">
      <p className="ui-eyebrow">Private workspace</p>
      <nav aria-label="Private workspace" className="console-nav">
        <NavLink to="/" end>
          Room overview
        </NavLink>
        <NavLink to="/session">Session setup</NavLink>
      </nav>
      <Button variant="quiet" onClick={signOut}>
        Leave workspace
      </Button>
    </aside>
  );
}

function PrivateLayout() {
  return (
    <Shell header={<ConsoleHeader />}>
      <PrivateNavigation />
      <div className="console-content">
        <Outlet />
      </div>
    </Shell>
  );
}

function OverviewPage() {
  return (
    <>
      <section className="console-hero ui-reveal ui-reveal--2" aria-labelledby="overview-title">
        <p className="ui-eyebrow">Room 01 / rehearsal</p>
        <h1 id="overview-title">Ready for the room</h1>
        <p className="console-lead">
          Prepare the private controller here, then let the public Stage enter fullscreen from its
          own screen.
        </p>
        <Link className="ui-button ui-button--primary console-action" to="/session">
          Prepare a session
        </Link>
      </section>
      <div className="console-grid ui-reveal ui-reveal--3">
        <Panel title="Display boundary">
          <Badge tone="accent">Separate public Stage</Badge>
          <p>Only audience-safe presentation material appears on the display surface.</p>
        </Panel>
        <Panel title="Topology">
          <p className="console-metric">2 modes</p>
          <p>Designed for Windows Extend and Duplicate with a separate controller device.</p>
        </Panel>
      </div>
    </>
  );
}

function SessionPage() {
  return (
    <section className="console-stack ui-reveal" aria-labelledby="session-title">
      <div>
        <p className="ui-eyebrow">Setup checklist</p>
        <h1 id="session-title">Session controls</h1>
        <p className="console-lead">
          This browser-only foundation stops before pairing, transport, capture, or publication
          protocols.
        </p>
      </div>
      <div className="console-grid">
        <Panel title="1. Choose the room" tone="inset">
          <p>Confirm the presentation title and target display before a future binding flow begins.</p>
        </Panel>
        <Panel title="2. Open public Stage" tone="inset">
          <p>Use a clean browser profile on the projected computer in either supported screen mode.</p>
        </Panel>
        <Panel title="3. Enter fullscreen there" tone="inset">
          <p>The Stage operator clicks fullscreen locally. Console never forces another window.</p>
        </Panel>
      </div>
    </section>
  );
}

export function ConsoleRoutes() {
  return (
    <Routes>
      <Route element={<PublicOnly />}>
        <Route path="/sign-in" element={<SignInPage />} />
      </Route>
      <Route element={<RequireAuth />}>
        <Route element={<PrivateLayout />}>
          <Route index element={<OverviewPage />} />
          <Route path="/session" element={<SessionPage />} />
        </Route>
      </Route>
      <Route path="*" element={<Navigate to="/sign-in" replace />} />
    </Routes>
  );
}

.console-rail {
  position: sticky;
  inset-block-start: var(--space-4);
  display: grid;
  gap: var(--space-6);
  padding: var(--space-6);
  border: var(--size-hairline) solid var(--border-subtle);
  border-radius: var(--radius-lg);
  background: var(--surface-inset);
}

.console-nav {
  display: grid;
  gap: var(--space-2);
}

.console-nav a {
  padding: var(--space-3) var(--space-4);
  border: var(--size-hairline) solid var(--color-transparent);
  border-radius: var(--radius-md);
  color: var(--text-secondary);
  text-decoration: none;
  transition:
    color var(--duration-fast) var(--ease-out),
    border-color var(--duration-fast) var(--ease-out),
    background var(--duration-fast) var(--ease-out);
}

.console-nav a:hover,
.console-nav a[aria-current="page"] {
  color: var(--text-primary);
  border-color: var(--border-emphasis);
  background: var(--surface-panel);
}

.console-content,
.console-stack {
  display: grid;
  gap: var(--space-8);
}

.console-hero {
  max-width: var(--size-copy);
  padding-block: var(--space-8) var(--space-12);
}

.console-hero h1,
.console-sign-in h1,
.console-stack h1 {
  max-width: var(--size-copy);
  margin: var(--space-2) var(--space-0) var(--space-5);
  font-family: var(--font-display);
  font-size: var(--text-display);
  font-weight: var(--weight-regular);
  line-height: var(--line-tight);
  letter-spacing: var(--tracking-tight);
}

.console-sign-in h1,
.console-stack h1 {
  font-size: var(--text-title);
}

.console-lead {
  max-width: var(--size-copy);
  color: var(--text-secondary);
  font-size: var(--text-lead);
}

.console-caption {
  margin-block: var(--space-5) var(--space-0);
  color: var(--text-secondary);
  font-size: var(--text-caption);
}

.console-action {
  width: fit-content;
  margin-block-start: var(--space-4);
}

.console-grid {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(var(--size-full), var(--size-card-min)), 1fr));
