{
  "name": "@impromptu/stage",
  "version": "0.0.0",
  "private": true,
  "type": "module",
  "scripts": {
    "dev": "vite --port 4174",
    "build": "vite build",
    "preview": "vite preview --port 4174",
    "typecheck": "tsc --noEmit"
  },
  "dependencies": {
    "@impromptu/ui": "workspace:*",
    "react": "19.1.1",
    "react-dom": "19.1.1",
    "react-router-dom": "7.8.2"
  },
  "devDependencies": {
    "@types/react": "19.1.10",
    "@types/react-dom": "19.1.7",
    "@vitejs/plugin-react": "5.0.2",
    "vite": "7.1.3"
  }
}

{
  "extends": "../../tsconfig.json",
  "compilerOptions": {
    "allowImportingTsExtensions": false,
    "jsx": "react-jsx",
    "lib": ["ES2023", "DOM", "DOM.Iterable"],
    "types": ["vite/client", "bun"]
  },
  "include": ["src/**/*.ts", "src/**/*.tsx", "vite.config.ts"]
}

import react from "@vitejs/plugin-react";
import { defineConfig } from "vite";

export default defineConfig({
  plugins: [react()],
  build: {
    sourcemap: true,
  },
});

const CACHE_NAME = "impromptu-stage-public-v1";
const APP_SHELL = ["/", "/index.html", "/manifest.webmanifest", "/icon.svg"];

self.addEventListener("install", (event) => {
  event.waitUntil(caches.open(CACHE_NAME).then((cache) => cache.addAll(APP_SHELL)));
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches
      .keys()
      .then((keys) =>
        Promise.all(keys.filter((key) => key !== CACHE_NAME).map((key) => caches.delete(key))),
      ),
  );
});

self.addEventListener("fetch", (event) => {
  const requestUrl = new URL(event.request.url);
  if (event.request.method !== "GET" || requestUrl.origin !== self.location.origin) {
    return;
  }

  event.respondWith(
    caches.match(event.request).then((cached) => cached ?? fetch(event.request)),
  );
});

export function registerStageServiceWorker() {
  if ("serviceWorker" in navigator && import.meta.env.PROD) {
    void navigator.serviceWorker.register("/sw.js", { scope: "/" });
  }
}

import "@impromptu/ui/styles.css";
import "./stage.css";

import { StrictMode } from "react";
import { createRoot } from "react-dom/client";
import { BrowserRouter } from "react-router-dom";

import { StageRoutes } from "./App";
import { registerStageServiceWorker } from "./registerServiceWorker";

const root = document.getElementById("root");

if (!root) {
  throw new Error("Stage root element is missing");
}

document.documentElement.dataset.surface = "stage";

createRoot(root).render(
  <StrictMode>
    <BrowserRouter>
      <StageRoutes />
    </BrowserRouter>
  </StrictMode>,
);

registerStageServiceWorker();

import { Badge, Brand, Button, Panel, Shell, StatusDot } from "@impromptu/ui";
import { useEffect, useId, useState } from "react";
import { Link, Navigate, Route, Routes } from "react-router-dom";

function StageHeader() {
  return (
    <>
      <Brand eyebrow="Public Stage" />
      <Badge tone="accent">
        <StatusDot label="Audience-safe surface" />
        Audience screen
      </Badge>
    </>
  );
}

function LandingPage() {
  const titleId = useId();

  return (
    <Shell focused header={<StageHeader />}>
      <section className="stage-welcome ui-reveal" aria-labelledby={titleId}>
        <p className="ui-eyebrow">Display setup</p>
        <h1 id={titleId}>A clean screen for the room</h1>
        <p className="stage-lead">
          This public-only surface contains no presenter controls, coaching, team notes, or private
          session state.
        </p>
        <Panel className="stage-join" tone="inset">
          <div>
            <p className="ui-eyebrow">Preview display code</p>
            <p className="stage-code" aria-label="Display code 7 K 4 Q">
              7K4Q
            </p>
          </div>
          <Link className="ui-button ui-button--primary" to="/display/rehearsal">
            Open display preview
          </Link>
        </Panel>
        <p className="stage-note">A future controller may approve this display code. It grants no access by itself.</p>
      </section>
    </Shell>
  );
}

interface FullscreenState {
  active: boolean;
  error: string | null;
}

function useStageFullscreen() {
  const [state, setState] = useState<FullscreenState>({ active: false, error: null });

  useEffect(() => {
    const syncFullscreen = () => {
      setState({ active: document.fullscreenElement !== null, error: null });
    };
    const reportError = () => {
      setState((current) => ({ ...current, error: "Fullscreen was blocked. Use the browser menu." }));
    };

    document.addEventListener("fullscreenchange", syncFullscreen);
    document.addEventListener("fullscreenerror", reportError);
    syncFullscreen();

    return () => {
      document.removeEventListener("fullscreenchange", syncFullscreen);
      document.removeEventListener("fullscreenerror", reportError);
    };
  }, []);

  const toggle = async () => {
    try {
      if (document.fullscreenElement) {
        await document.exitFullscreen();
      } else if (document.documentElement.requestFullscreen) {
        await document.documentElement.requestFullscreen();
      } else {
        setState((current) => ({ ...current, error: "Fullscreen is not available in this browser." }));
      }
    } catch {
      setState((current) => ({ ...current, error: "Fullscreen was blocked. Use the browser menu." }));
    }
  };

  return { ...state, toggle };
}

function DisplayPage() {
  const titleId = useId();
  const fullscreen = useStageFullscreen();

  return (
    <div className="stage-display">
      <header className="stage-display__bar">
        <Brand eyebrow="Public Stage" />
        <div className="stage-display__actions">
          <Badge tone="success">
            <StatusDot label="Preview content visible" />
            Preview
          </Badge>
          <Button variant="quiet" onClick={() => void fullscreen.toggle()}>
            {fullscreen.active ? "Exit fullscreen" : "Enter fullscreen"}
          </Button>
        </div>
      </header>
      <main className="stage-display__content" aria-labelledby={titleId}>
        <section className="stage-claim ui-reveal">
          <p className="ui-eyebrow">Curated evidence preview</p>
          <h1 id={titleId}>Evidence, without the detour</h1>
          <p className="stage-lead">
            A single, presenter-approved card supports the current idea while the main presentation
            keeps moving.
          </p>
        </section>
        <Panel className="stage-evidence ui-reveal ui-reveal--2">
          <Badge tone="accent">Pre-approved</Badge>
          <blockquote>
            Supporting material stays legible at distance, cites its origin, and never reveals the
            presenter&apos;s private workspace.
          </blockquote>
          <footer>
            <span>Impromptu demo principle</span>
            <span>Prepared for rehearsal</span>
          </footer>
        </Panel>
      </main>
      <p className="stage-fullscreen-message" aria-live="polite">
        {fullscreen.error ?? (fullscreen.active ? "Fullscreen is active." : "Fullscreen is ready.")}
      </p>
    </div>
  );
}

export function StageRoutes() {
  return (
    <Routes>
      <Route index element={<LandingPage />} />
      <Route path="/display/:displayId" element={<DisplayPage />} />
      <Route path="*" element={<Navigate to="/" replace />} />
    </Routes>
  );
}

.stage-welcome {
  display: grid;
  gap: var(--space-5);
  padding-block: var(--space-8);
}

.stage-welcome h1,
.stage-claim h1 {
  margin: var(--space-0);
  font-family: var(--font-display);
  font-size: var(--text-display);
  font-weight: var(--weight-regular);
  line-height: var(--line-tight);
  letter-spacing: var(--tracking-tight);
}

.stage-lead {
  max-width: var(--size-copy);
  margin: var(--space-0);
  color: var(--text-secondary);
  font-size: var(--text-lead);
}

.stage-join {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-6);
  align-items: center;
  justify-content: space-between;
  margin-block-start: var(--space-6);
}

.stage-code {
  margin: var(--space-0);
  font-family: var(--font-mono);
  font-size: var(--text-title);
  font-weight: var(--weight-bold);
  letter-spacing: var(--tracking-wide);
}

.stage-note {
  max-width: var(--size-copy);
  color: var(--text-secondary);
  font-size: var(--text-small);
}

.stage-display {
  width: var(--size-full);
  min-height: var(--size-viewport);
  padding: clamp(var(--space-4), 3vw, var(--space-8));
}

.stage-display__bar,
.stage-display__actions {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  align-items: center;
  justify-content: space-between;
}

.stage-display__content {
  display: grid;
  grid-template-columns: repeat(auto-fit, minmax(min(var(--size-full), var(--size-card-min)), var(--fraction-full)));
  gap: clamp(var(--space-6), 6vw, var(--space-16));
  align-items: center;
  min-height: calc(var(--size-viewport) - var(--space-20));
  padding-block: var(--space-8);
}

.stage-claim {
  display: grid;
  gap: var(--space-5);
}

.stage-evidence {
  border-color: var(--color-accent);
  transform: rotate(var(--rotate-accent));
}

.stage-evidence blockquote {
  margin: var(--space-8) var(--space-0);
  font-family: var(--font-display);
  font-size: var(--text-title);
  line-height: var(--line-title);
  letter-spacing: var(--tracking-tight);
}

.stage-evidence footer {
  display: flex;
  flex-wrap: wrap;
  gap: var(--space-3);
  justify-content: space-between;
  color: var(--text-secondary);
  font-family: var(--font-mono);
  font-size: var(--text-caption);
  letter-spacing: var(--tracking-wide);
  text-transform: uppercase;
}

.stage-fullscreen-message {
  position: fixed;
  inset-inline-end: var(--space-4);
  inset-block-end: var(--space-4);
  margin: var(--space-0);
  padding: var(--space-2) var(--space-3);
  border-radius: var(--radius-pill);
  color: var(--text-secondary);
  background: var(--surface-panel);
  font-size: var(--text-caption);
  box-shadow: var(--shadow-panel);
}

