      const path = join(root, name);
      if (name === "dist" || name === "node_modules") {
        return [];
      }
      return statSync(path).isDirectory() ? filesUnder(path, extensions) : [path];
    })
    .filter((path) => !extensions || extensions.has(extname(path)));
}

function importSpecifiers(source: string): string[] {
