    expect(stageWorker).toContain("impromptu-stage-public-v1");
    expect(consoleWorker).not.toContain("impromptu-stage-public-v1");
    expect(stageWorker).not.toContain("impromptu-console-shell-v1");
  });

  test("keeps every browser import graph free of services, models, and providers", () => {
    for (const root of browserRoots) {
      const sourceFiles = filesUnder(root, new Set([".ts", ".tsx", ".js"]));
      for (const file of sourceFiles) {
        const source = readFileSync(file, "utf8");
        for (const specifier of importSpecifiers(source)) {
