+    for (const path of ["apps/console/src/console.css", "apps/stage/src/stage.css"]) {
+      const css = readFileSync(path, "utf8");
+      expect(css).not.toMatch(/#[0-9a-f]{3,8}|rgba?\(|oklch\(/i);
