const CACHE_PREFIX = "impromptu-console-shell-";
const CACHE_NAME = "impromptu-console-shell-b6c741f62506";
const PRECACHE_URLS = [
  "/assets/index-B5p1Q8Al.css",
  "/assets/index-OU41nZFj.js",
  "/icon.svg",
  "/index.html",
  "/manifest.webmanifest"
];

self.addEventListener("install", (event) => {
  event.waitUntil(
    caches.open(CACHE_NAME).then(async (cache) => {
      await cache.addAll(PRECACHE_URLS);
      await self.skipWaiting();
    }),
  );
});

self.addEventListener("activate", (event) => {
  event.waitUntil(
    caches.keys().then(async (keys) => {
      await Promise.all(
        keys
          .filter((key) => key.startsWith(CACHE_PREFIX) && key !== CACHE_NAME)
          .map((key) => caches.delete(key)),
      );
      await self.clients.claim();
    }),
  );
});

async function serveRequest(request) {
  const requestUrl = new URL(request.url);
  if (request.method !== "GET" || requestUrl.origin !== self.location.origin) {
    return fetch(request);
  }

  const shellCache = await caches.open(CACHE_NAME);
  if (request.mode === "navigate") {
    try {
      return await fetch(request);
    } catch {
      return (await shellCache.match("/index.html", { ignoreSearch: true })) ?? Response.error();
    }
  }

  return (await shellCache.match(request)) ?? fetch(request);
}

self.addEventListener("fetch", (event) => {
  event.respondWith(serveRequest(event.request));
});

