class CleanupStack {
  readonly #tasks: Array<() => Promise<void>> = [];

  add(task: CleanupTask) {
    let result: Promise<void> | null = null;
    const run = () => {
      result ??= Promise.resolve().then(task);
      return result;
    };
    this.#tasks.push(run);
    return run;
